import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int calls = in.nextInt();
        int seconds = in.nextInt();
        System.out.println(calls * 5 + seconds * 2);
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int calls, seconds;
    cin >> calls >> seconds;
    cout << calls * 5 + seconds * 2 << endl;
    return 0;
}
